import{_ as i,C as d,o as r,c as n,j as t,a,b as l,w as s,E as c,a3 as h,a2 as p}from"./chunks/framework.CWWEQfK7.js";const C=JSON.parse('{"title":"Debug analysis and retrieval","description":"Diagnose analysis, retrieval, and MCP failures by separating process, dependency, queue, freshness, and evidence layers.","frontmatter":{"page_id":"guide-debugging","description":"Diagnose analysis, retrieval, and MCP failures by separating process, dependency, queue, freshness, and evidence layers."},"headers":[],"relativePath":"en/guide/debugging.md","filePath":"en/guide/debugging.md","lastUpdated":1786289447000}'),u={name:"en/guide/debugging.md"};function m(y,e,b,g,f,k){const o=d("Mermaid");return r(),n("div",null,[e[1]||(e[1]=t("h1",{id:"debug-analysis-and-retrieval",tabindex:"-1"},[a("Debug analysis and retrieval "),t("a",{class:"header-anchor",href:"#debug-analysis-and-retrieval","aria-label":'Permalink to "Debug analysis and retrieval"'},"​")],-1)),e[2]||(e[2]=t("p",null,"When troubleshooting Ershu, separate four questions: is the process alive, are its dependencies usable, did the run complete, and are the results current enough? Each has a different check. One green health endpoint cannot prove the whole system is ready.",-1)),e[3]||(e[3]=t("h2",{id:"locate-the-failing-layer-first",tabindex:"-1"},[a("Locate the failing layer first "),t("a",{class:"header-anchor",href:"#locate-the-failing-layer-first","aria-label":'Permalink to "Locate the failing layer first"'},"​")],-1)),(r(),l(h,null,{default:s(()=>[c(o,{id:"mermaid-9",class:"ershu-mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22Page%20or%20tool%20fails%22%5D%20--%3E%20B%7B%22Is%20API%20or%20MCP%20alive%3F%22%7D%0A%20%20B%20--%3E%7C%22No%22%7C%20C%5B%22Inspect%20startup%20logs%20and%20environment%22%5D%0A%20%20B%20--%3E%7C%22Yes%22%7C%20D%7B%22Does%20the%20API%20dependency%20check%20pass%3F%22%7D%0A%20%20D%20--%3E%7C%22No%22%7C%20E%5B%22Inspect%20PostgreSQL%20or%20Milvus%22%5D%0A%20%20D%20--%3E%7C%22Yes%22%7C%20F%7B%22Is%20the%20run%20progressing%3F%22%7D%0A%20%20F%20--%3E%7C%22No%22%7C%20G%5B%22Inspect%20Worker%2C%20queue%2C%20and%20run%20error%22%5D%0A%20%20F%20--%3E%7C%22Yes%22%7C%20H%7B%22Are%20results%20current%20and%20complete%3F%22%7D%0A%20%20H%20--%3E%7C%22No%22%7C%20I%5B%22Inspect%20commit%2C%20freshness%2C%20degradation%2C%20and%20truncation%22%5D%0A%20%20H%20--%3E%7C%22Yes%22%7C%20J%5B%22Continue%20with%20permissions%2C%20query%20scope%2C%20and%20evidence%20authority%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=p(`<h2 id="layer-1-confirm-the-process-not-the-whole-system" tabindex="-1">Layer 1: confirm the process, not the whole system <a class="header-anchor" href="#layer-1-confirm-the-process-not-the-whole-system" aria-label="Permalink to &quot;Layer 1: confirm the process, not the whole system&quot;">​</a></h2><p>These are recommended probes. They have not been run against your deployment:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8000/health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8000/api/v1/health/dependencies</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8001/health</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><table tabindex="0"><thead><tr><th>Check</th><th>What it proves</th><th>What it does not prove</th></tr></thead><tbody><tr><td>API <code>/health</code></td><td>The API process responds over HTTP</td><td>Database, Milvus, Redis, Worker, or model channels are usable</td></tr><tr><td>API <code>/api/v1/health/dependencies</code></td><td>Individual PostgreSQL and Milvus probe results</td><td>Redis, Worker, model channels, or repository credentials are usable</td></tr><tr><td>MCP <code>/health</code></td><td>The MCP process responds over HTTP</td><td>Database, authentication, project permission, or all 27 tools work</td></tr><tr><td>MCP <code>get_server_info</code></td><td>Credentials and protocol work, and the process returns tools and build identity</td><td>A particular project&#39;s indexes are complete</td></tr><tr><td>Worker remains running</td><td>Startup validation and structured-parser self-check passed</td><td>A particular run will complete</td></tr></tbody></table><p>The Worker has no HTTP health endpoint. At startup it validates <code>ENCRYPTION_KEY</code>, analysis registries, database access, and the structured parser. Any of those can stop the process. The final proof is still an actual queued run advancing.</p><h2 id="layer-2-the-run-is-queued-but-does-not-move" tabindex="-1">Layer 2: the run is queued but does not move <a class="header-anchor" href="#layer-2-the-run-is-queued-but-does-not-move" aria-label="Permalink to &quot;Layer 2: the run is queued but does not move&quot;">​</a></h2><p>Open the run detail first. Record the run identifier, current state, last event, and error before rebuilding anything.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely boundary</th><th>Observable next check</th></tr></thead><tbody><tr><td>Remains queued</td><td>No Worker, a different database, or a failure to claim work</td><td>Confirm API and Worker share <code>DATABASE_URL</code>; Worker logs should show startup and queue polling</td></tr><tr><td>Fails shortly after starting</td><td>Key, repository credential, model channel, parser, or external dependency</td><td>Inspect the run error and Worker logs from the same time; the error should identify the failed stage</td></tr><tr><td>Waiting for user input</td><td>Agent questions are enabled and awaiting an answer</td><td>Answer on the run page or wait for the configured timeout behavior</td></tr><tr><td>Completed with warnings</td><td>Documents may be published while a later search-index step degraded</td><td>Read warnings and each layer&#39;s state instead of treating “completed” as fully indexed</td></tr><tr><td>Scheduled check creates no run</td><td>Poller is not separate, cron is not due, Redis lease was not acquired, or the commit is current</td><td>Inspect last-poll time and <code>repository.poll_scheduled</code> audit records</td></tr></tbody></table><p>The run-queue lease timeout defaults to <code>600</code> seconds. The Worker can recover interrupted work whose lease has expired, but shortening the lease is not a substitute for fixing a Worker that repeatedly crashes.</p><h2 id="layer-3-the-repository-cannot-be-prepared" tabindex="-1">Layer 3: the repository cannot be prepared <a class="header-anchor" href="#layer-3-the-repository-cannot-be-prepared" aria-label="Permalink to &quot;Layer 3: the repository cannot be prepared&quot;">​</a></h2><p>For a remote repository, inspect the registered URL, default branch, and credential first. A private repository can use its stored credential or a repository-type <code>GITHUB_TOKEN</code> or <code>GITLAB_TOKEN</code>. Git commands time out after <code>120</code> seconds by default.</p><p>A local repository must also satisfy all of these conditions:</p><ul><li>the path exists in the running process&#39;s filesystem;</li><li><code>TRUSTED_LOCAL_PATHS</code> covers it;</li><li>the development escape hatch is disabled in production; and</li><li>if the Worker analyzes it and MCP reads it, both hosts can see the registered path.</li></ul><p>A poll returns <code>local_workspace_dirty</code> for uncommitted local changes and <code>repository_has_no_git_commit</code> when no Git commit exists. These are deliberate skips, not queue failures.</p><h2 id="layer-4-search-is-empty-or-degraded" tabindex="-1">Layer 4: search is empty or degraded <a class="header-anchor" href="#layer-4-search-is-empty-or-degraded" aria-label="Permalink to &quot;Layer 4: search is empty or degraded&quot;">​</a></h2><p>Inspect <code>mode</code>, <code>degraded</code>, <code>degradation_reason</code>, <code>retrieval_sources</code>, and <code>fallback_used</code> in the response.</p><ul><li><code>keyword</code> uses lexical results only.</li><li><code>semantic</code> accepts semantic results only. If no embedding channel, usable index, or Milvus query is available, it fails explicitly and never presents keyword hits as semantic matches.</li><li><code>hybrid</code> combines semantic and keyword results. If the semantic branch is unavailable, it may return keywords while explicitly reporting degradation and fallback.</li></ul><p>Then inspect <code>search_index_status</code> on the repository or run result. <code>indexing</code> means background work is still running. Repository states <code>keyword_only</code> and <code>degraded</code>, and run states <code>degraded</code> and <code>unavailable</code>, all mean that semantic retrieval is not fully available. With background search indexing enabled, an analysis run may complete before the index does.</p><p>When only documents match, the response may report <code>documents_fallback</code>. Treat those hits as navigation, not implementation evidence, and verify them in source.</p><h2 id="layer-5-graphs-or-change-surfaces-look-incomplete" tabindex="-1">Layer 5: graphs or change surfaces look incomplete <a class="header-anchor" href="#layer-5-graphs-or-change-surfaces-look-incomplete" aria-label="Permalink to &quot;Layer 5: graphs or change surfaces look incomplete&quot;">​</a></h2><p>Graph and change-surface queries are bounded. Inspect:</p><ul><li>whether <code>data_status</code> is <code>available</code>, <code>partial</code>, <code>stale</code>, or <code>unavailable</code>;</li><li>whether <code>result_status</code> is unknown because data is unavailable;</li><li>repository coverage, repositories without matches, the query <code>limit</code>, and truncation;</li><li><code>direct</code> versus <code>related</code> classification and confidence; and</li><li>whether the latest observed repository commit matches the indexed commit.</li></ul><p>“No result” does not always mean “no relationship.” When data is unavailable, the correct conclusion is unknown. When output is truncated, it is a bounded candidate set, not an exhaustive list.</p><h2 id="layer-6-a-document-disagrees-with-source" tabindex="-1">Layer 6: a document disagrees with source <a class="header-anchor" href="#layer-6-a-document-disagrees-with-source" aria-label="Permalink to &quot;Layer 6: a document disagrees with source&quot;">​</a></h2><p>Use this order:</p><ol><li>Inspect the document branch, commit, and freshness.</li><li>Inspect <code>authority</code>. AI-authored documents are <code>secondary</code>; source and structured contracts are <code>source_derived</code>.</li><li>Locate the path through the tree and code index.</li><li>Verify exact fields, defaults, and behavior with <code>read_code_context</code> or the current local source.</li></ol><p>Current source wins when it conflicts with a document. <code>refresh_repository_facts</code> refreshes four fact layers but does not rewrite documents, so a fact refresh is not proof that the prose changed.</p><h2 id="report-a-problem-with-evidence" tabindex="-1">Report a problem with evidence <a class="header-anchor" href="#report-a-problem-with-evidence" aria-label="Permalink to &quot;Report a problem with evidence&quot;">​</a></h2><p>A reproducible report should include:</p><ul><li>the module and process entry point;</li><li>project, repository, and run identifiers, without any secret;</li><li>repository branch, commit, and freshness;</li><li>the first failing state or error class;</li><li>database and Milvus results from the API dependency check;</li><li>relevant Worker, API, or MCP logs from the same time window;</li><li>query mode, degradation, fallback, coverage, and truncation metadata; and</li><li>the shortest repeatable steps.</li></ul><p>Never attach <code>SECRET_KEY</code>, <code>ENCRYPTION_KEY</code>, <code>MCP_KEY_PEPPER</code>, an MCP key, a webhook secret, or repository credentials.</p><blockquote><p>Primary source locations: <code>api/src/ershu/api/routes/health.py</code>, <code>worker/src/ershu/workers/analysis.py</code>, <code>core/src/ershu/services/retrieval.py</code>, <code>core/src/ershu/services/repositories/freshness.py</code>, and <code>mcp/src/ershu/mcp/tool_runtime.py</code>.</p></blockquote>`,32))])}const w=i(u,[["render",m]]);export{C as __pageData,w as default};
